     1→/**
     2→ * FreeWire - Phase 4: 노드 에디터 UI
     3→ * 순수 Canvas + SVG 기반 (외부 의존성 없음)
     4→ *
     5→ * 기능:
     6→ * - 노드 드래그/이동
     7→ * - 포트 연결 (호환 타입 검증)
     8→ * - 실시간 SVG 와이어 렌더링 (베지어 곡선)
     9→ * - 노드 팔레트 (component/data/logic)
    10→ * - FreeExecutor API 연동 (컴파일 + 실행)
    11→ * - 그래프 JSON 직렬화/역직렬화
    12→ */
    13→
    14→'use strict';
    15→
    16→// ─── 포트 타입 컬러 ──────────────────────────────────────────────
    17→const PORT_COLORS = {
    18→  component: '#58a6ff',
    19→  data:      '#3fb950',
    20→  logic:     '#d29922',
    21→  event:     '#bc8cff',
    22→  any:       '#8b949e',
    23→};
    24→
    25→const PORT_COMPAT = {
    26→  component: ['component', 'any'],
    27→  data:      ['data', 'any'],
    28→  logic:     ['logic', 'any'],
    29→  event:     ['event', 'any'],
    30→  any:       ['component', 'data', 'logic', 'event', 'any'],
    31→};
    32→
    33→// ─── 노드 팔레트 정의 ────────────────────────────────────────────
    34→const NODE_PALETTE = [
    35→  {
    36→    label: '컴포넌트',
    37→    nodes: [
    38→      { label: '버튼', type: 'component', subtype: 'button',
    39→        inputs: [{ name: 'props', portType: 'data' }, { name: 'onClick', portType: 'logic' }],
    40→        outputs: [{ name: 'element', portType: 'component' }],
    41→        props: { label: '클릭', variant: 'primary' } },
    42→      { label: '텍스트', type: 'component', subtype: 'text',
    43→        inputs: [{ name: 'content', portType: 'data' }],
    44→        outputs: [{ name: 'element', portType: 'component' }],
    45→        props: { content: '텍스트', tag: 'p' } },
    46→      { label: '입력', type: 'component', subtype: 'input',
    47→        inputs: [{ name: 'value', portType: 'data' }, { name: 'onChange', portType: 'logic' }],
    48→        outputs: [{ name: 'element', portType: 'component' }, { name: 'value', portType: 'data' }],
    49→        props: { placeholder: '입력하세요', type: 'text' } },
    50→      { label: '카드', type: 'component', subtype: 'card',
    51→        inputs: [{ name: 'title', portType: 'data' }, { name: 'children', portType: 'component' }],
    52→        outputs: [{ name: 'element', portType: 'component' }],
    53→        props: { title: '카드 제목' } },
    54→      { label: '컨테이너', type: 'component', subtype: 'container',
    55→        inputs: [{ name: 'children', portType: 'component' }],
    56→        outputs: [{ name: 'element', portType: 'component' }],
    57→        props: { direction: 'column', gap: '8px' } },
    58→    ],
    59→  },
    60→  {
    61→    label: '데이터',
    62→    nodes: [
    63→      { label: '상수', type: 'data', subtype: 'const',
    64→        inputs: [],
    65→        outputs: [{ name: 'value', portType: 'data' }],
    66→        props: { value: '42', valueType: 'number' } },
    67→      { label: '상태', type: 'data', subtype: 'state',
    68→        inputs: [{ name: 'set', portType: 'data' }],
    69→        outputs: [{ name: 'value', portType: 'data' }],
    70→        props: { name: 'count', initial: '0' } },
    71→      { label: '배열', type: 'data', subtype: 'array',
    72→        inputs: [],
    73→        outputs: [{ name: 'items', portType: 'data' }],
    74→        props: { items: '[]' } },
    75→      { label: 'Props', type: 'data', subtype: 'props',
    76→        inputs: [],
    77→        outputs: [{ name: 'props', portType: 'data' }],
    78→        props: { fields: '{}' } },
    79→    ],
    80→  },
    81→  {
    82→    label: '로직',
    83→    nodes: [
    84→      { label: '이벤트핸들러', type: 'logic', subtype: 'handler',
    85→        inputs: [{ name: 'action', portType: 'logic' }],
    86→        outputs: [{ name: 'handler', portType: 'logic' }],
    87→        props: { name: 'handleClick' } },
    88→      { label: 'setState', type: 'logic', subtype: 'setState',
    89→        inputs: [{ name: 'trigger', portType: 'event' }, { name: 'value', portType: 'data' }],
    90→        outputs: [{ name: 'done', portType: 'event' }],
    91→        props: { target: '' } },
    92→      { label: 'if/else', type: 'logic', subtype: 'condition',
    93→        inputs: [{ name: 'condition', portType: 'data' }],
    94→        outputs: [{ name: 'true', portType: 'logic' }, { name: 'false', portType: 'logic' }],
    95→        props: { operator: '==', value: 'true' } },
    96→    ],
    97→  },
    98→];
    99→
   100→// ─── NodeEditorUI 클래스 ─────────────────────────────────────────
   101→
   102→class NodeEditorUI {
   103→  constructor(container) {
   104→    this.container = container;
   105→    this.nodes = new Map();        // id → NodeView
   106→    this.wires = new Map();        // id → WireView
   107→    this.nodeIdCounter = 1;
   108→    this.wireIdCounter = 1;
   109→
   110→    this.selectedNode = null;
   111→    this.dragState = null;         // 노드 드래그
   112→    this.wireState = null;         // 와이어 드래그 중
   113→
   114→    this.viewport = { x: 0, y: 0, scale: 1 };
   115→    this.panState = null;
   116→
   117→    this._build();
   118→    this._bindEvents();
   119→  }
   120→
   121→  // ─── UI 빌드 ──────────────────────────────────────────────────
   122→
   123→  _build() {
   124→    this.container.innerHTML = '';
   125→    this.container.style.cssText = 'display:flex;flex-direction:row;height:100%;overflow:hidden;background:#0d1117;';
   126→
   127→    // 팔레트
   128→    this.paletteEl = document.createElement('div');
   129→    this.paletteEl.className = 'fw-palette';
   130→    this.paletteEl.style.cssText = `
   131→      width:180px;flex-shrink:0;background:#161b22;border-right:1px solid #30363d;
   132→      overflow-y:auto;display:flex;flex-direction:column;
   133→    `;
   134→    this._buildPalette();
   135→
   136→    // 캔버스 영역
   137→    this.canvasWrap = document.createElement('div');
   138→    this.canvasWrap.style.cssText = 'flex:1;position:relative;overflow:hidden;';
   139→
   140→    // SVG 와이어 레이어
   141→    this.svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
   142→    this.svg.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:1;';
   143→    this.svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
   144→
   145→    // 그리드 패턴
   146→    this.svg.innerHTML = `
   147→      <defs>
   148→        <pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse">
   149→          <path d="M 20 0 L 0 0 0 20" fill="none" stroke="rgba(255,255,255,0.04)" stroke-width="1"/>
   150→        </pattern>
   151→        <marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto">
   152→          <path d="M 0 0 L 0 6 L 9 3 z" fill="#58a6ff" opacity="0.8"/>
   153→        </marker>
   154→      </defs>
   155→      <rect width="100%" height="100%" fill="url(#grid)"/>
   156→      <g class="wires-layer"></g>
   157→      <path class="wire-preview" d="" fill="none" stroke="#58a6ff" stroke-width="2" stroke-dasharray="6,3" opacity="0.7"/>
   158→    `;
   159→
   160→    this.wiresLayer = this.svg.querySelector('.wires-layer');
   161→    this.wirePreview = this.svg.querySelector('.wire-preview');
   162→
   163→    // 노드 레이어 (div, SVG 위)
   164→    this.nodesLayer = document.createElement('div');
   165→    this.nodesLayer.style.cssText = 'position:absolute;inset:0;z-index:2;';
   166→
   167→    this.canvasWrap.appendChild(this.svg);
   168→    this.canvasWrap.appendChild(this.nodesLayer);
   169→
   170→    // 툴바
   171→    this.toolbar = document.createElement('div');
   172→    this.toolbar.style.cssText = `
   173→      position:absolute;top:8px;right:8px;z-index:10;
   174→      display:flex;gap:6px;
   175→    `;
   176→    this.toolbar.innerHTML = `
   177→      <button class="fw-btn" data-action="compile" title="FreeLang으로 컴파일">⚡ 컴파일</button>
   178→      <button class="fw-btn" data-action="run" title="실행">▶ 실행</button>
   179→      <button class="fw-btn" data-action="clear" title="전체 삭제">🗑️ 초기화</button>
   180→      <button class="fw-btn" data-action="export" title="JSON 내보내기">📤 내보내기</button>
   181→      <button class="fw-btn" data-action="import" title="JSON 가져오기">📥 가져오기</button>
   182→      <button class="fw-btn" data-action="fit" title="화면 맞추기">⊕ 맞추기</button>
   183→    `;
   184→    this.canvasWrap.appendChild(this.toolbar);
   185→
   186→    // 출력 패널
   187→    this.outputPanel = document.createElement('div');
   188→    this.outputPanel.style.cssText = `
   189→      position:absolute;bottom:0;left:0;right:0;height:160px;
   190→      background:rgba(13,17,23,.95);border-top:1px solid #30363d;
   191→      font-family:monospace;font-size:12px;z-index:10;display:flex;flex-direction:column;
   192→    `;
   193→    this.outputPanel.innerHTML = `
   194→      <div style="display:flex;align-items:center;gap:8px;padding:4px 10px;background:#21262d;border-bottom:1px solid #30363d;flex-shrink:0;">
   195→        <span style="color:#8b949e;font-size:11px;">출력</span>
   196→        <span class="fw-output-lang" style="color:#58a6ff;font-size:11px;"></span>
   197→        <button class="fw-btn fw-btn-sm" data-action="clear-output" style="margin-left:auto;">지우기</button>
   198→      </div>
   199→      <pre class="fw-output-content" style="flex:1;overflow:auto;padding:8px 12px;margin:0;color:#e6edf3;white-space:pre-wrap;word-break:break-all;"></pre>
   200→    `;
   201→    this.canvasWrap.appendChild(this.outputPanel);
   202→
   203→    this.container.appendChild(this.paletteEl);
   204→    this.container.appendChild(this.canvasWrap);
   205→
   206→    // 출력 높이 반영
   207→    this.nodesLayer.style.bottom = '160px';
   208→    this.svg.style.bottom = '160px';
   209→    this.svg.style.height = 'calc(100% - 160px)';
   210→  }
   211→
   212→  _buildPalette() {
   213→    this.paletteEl.innerHTML = `<div style="padding:8px 10px;font-size:11px;font-weight:700;color:#58a6ff;border-bottom:1px solid #30363d;">📦 노드 팔레트</div>`;
   214→
   215→    for (const group of NODE_PALETTE) {
   216→      const header = document.createElement('div');
   217→      header.style.cssText = 'padding:6px 10px;font-size:10px;font-weight:700;color:#8b949e;text-transform:uppercase;letter-spacing:0.8px;margin-top:4px;';
   218→      header.textContent = group.label;
   219→      this.paletteEl.appendChild(header);
   220→
   221→      for (const def of group.nodes) {
   222→        const item = document.createElement('div');
   223→        item.className = 'fw-palette-item';
   224→        item.style.cssText = `
   225→          padding:7px 12px;cursor:grab;font-size:12px;color:#e6edf3;
   226→          border-radius:4px;margin:1px 4px;transition:background .1s;
   227→          display:flex;align-items:center;gap:6px;
   228→        `;
   229→        const dot = document.createElement('span');
   230→        dot.style.cssText = `width:8px;height:8px;border-radius:50%;background:${PORT_COLORS[def.type] ?? '#8b949e'};flex-shrink:0;`;
   231→        item.appendChild(dot);
   232→        item.appendChild(document.createTextNode(def.label));
   233→
   234→        item.addEventListener('mouseenter', () => item.style.background = 'rgba(255,255,255,.07)');
   235→        item.addEventListener('mouseleave', () => item.style.background = '');
   236→
   237→        // 더블클릭: 캔버스 중앙에 추가
   238→        item.addEventListener('dblclick', () => {
   239→          const rect = this.canvasWrap.getBoundingClientRect();
   240→          const x = (rect.width / 2 - this.viewport.x) / this.viewport.scale - 80;
   241→          const y = (rect.height / 2 - this.viewport.y) / this.viewport.scale - 40;
   242→          this._addNode(def, x, y);
   243→        });
   244→
   245→        // 드래그로 추가
   246→        item.setAttribute('draggable', 'true');
   247→        item.addEventListener('dragstart', (e) => {
   248→          e.dataTransfer.setData('fw-node-def', JSON.stringify(def));
   249→        });
   250→
   251→        this.paletteEl.appendChild(item);
   252→      }
   253→    }
   254→  }
   255→
   256→  // ─── 이벤트 바인딩 ────────────────────────────────────────────
   257→
   258→  _bindEvents() {
   259→    // 드롭 영역
   260→    this.canvasWrap.addEventListener('dragover', (e) => e.preventDefault());
   261→    this.canvasWrap.addEventListener('drop', (e) => {
   262→      e.preventDefault();
   263→      const raw = e.dataTransfer.getData('fw-node-def');
   264→      if (!raw) return;
   265→      const def = JSON.parse(raw);
   266→      const rect = this.canvasWrap.getBoundingClientRect();
   267→      const x = (e.clientX - rect.left - this.viewport.x) / this.viewport.scale - 80;
   268→      const y = (e.clientY - rect.top - this.viewport.y) / this.viewport.scale - 40;
   269→      this._addNode(def, x, y);
   270→    });
   271→
   272→    // 툴바 버튼
   273→    this.toolbar.addEventListener('click', (e) => {
   274→      const btn = e.target.closest('[data-action]');
   275→      if (!btn) return;
   276→      this._handleToolbar(btn.dataset.action);
   277→    });
   278→
   279→    this.outputPanel.addEventListener('click', (e) => {
   280→      const btn = e.target.closest('[data-action]');
   281→      if (btn?.dataset.action === 'clear-output') {
   282→        this.outputPanel.querySelector('.fw-output-content').textContent = '';
   283→        this.outputPanel.querySelector('.fw-output-lang').textContent = '';
   284→      }
   285→    });
   286→
   287→    // 캔버스 패닝
   288→    this.canvasWrap.addEventListener('mousedown', (e) => {
   289→      if (e.target === this.canvasWrap || e.target === this.svg || e.target.tagName === 'rect') {
   290→        this.panState = { startX: e.clientX - this.viewport.x, startY: e.clientY - this.viewport.y };
   291→        this.canvasWrap.style.cursor = 'grabbing';
   292→      }
   293→    });
   294→
   295→    document.addEventListener('mousemove', (e) => {
   296→      if (this.panState) {
   297→        this.viewport.x = e.clientX - this.panState.startX;
   298→        this.viewport.y = e.clientY - this.panState.startY;
   299→        this._applyViewport();
   300→      }
   301→      if (this.dragState) {
   302→        this._onNodeDrag(e);
   303→      }
   304→      if (this.wireState) {
   305→        this._onWireDrag(e);
   306→      }
   307→    });
   308→
   309→    document.addEventListener('mouseup', (e) => {
   310→      if (this.panState) {
   311→        this.panState = null;
   312→        this.canvasWrap.style.cursor = '';
   313→      }
   314→      if (this.dragState) {
   315→        this.dragState = null;
   316→      }
   317→      if (this.wireState) {
   318→        this._onWireDrop(e);
   319→      }
   320→    });
   321→
   322→    // 줌
   323→    this.canvasWrap.addEventListener('wheel', (e) => {
   324→      e.preventDefault();
   325→      const delta = e.deltaY > 0 ? 0.9 : 1.1;
   326→      const rect = this.canvasWrap.getBoundingClientRect();
   327→      const mx = e.clientX - rect.left;
   328→      const my = e.clientY - rect.top;
   329→
   330→      this.viewport.x = mx - (mx - this.viewport.x) * delta;
   331→      this.viewport.y = my - (my - this.viewport.y) * delta;
   332→      this.viewport.scale = Math.max(0.2, Math.min(3, this.viewport.scale * delta));
   333→      this._applyViewport();
   334→    }, { passive: false });
   335→
   336→    // 선택 해제
   337→    this.nodesLayer.addEventListener('mousedown', (e) => {
   338→      if (e.target === this.nodesLayer) this._selectNode(null);
   339→    });
   340→  }
   341→
   342→  // ─── 뷰포트 ───────────────────────────────────────────────────
   343→
   344→  _applyViewport() {
   345→    this.nodesLayer.style.transform = `translate(${this.viewport.x}px,${this.viewport.y}px) scale(${this.viewport.scale})`;
   346→    this.nodesLayer.style.transformOrigin = '0 0';
   347→
   348→    // SVG 그리드 업데이트
   349→    const grid = this.svg.querySelector('pattern');
   350→    if (grid) {
   351→      const s = this.viewport.scale;
   352→      grid.setAttribute('width', 20 * s);
   353→      grid.setAttribute('height', 20 * s);
   354→      grid.setAttribute('patternTransform', `translate(${this.viewport.x % (20 * s)},${this.viewport.y % (20 * s)})`);
   355→    }
   356→
   357→    this._redrawAllWires();
   358→  }
   359→
   360→  _fitView() {
   361→    if (this.nodes.size === 0) return;
   362→    let minX=Infinity, minY=Infinity, maxX=-Infinity, maxY=-Infinity;
   363→    for (const nv of this.nodes.values()) {
   364→      minX = Math.min(minX, nv.x);
   365→      minY = Math.min(minY, nv.y);
   366→      maxX = Math.max(maxX, nv.x + nv.width);
   367→      maxY = Math.max(maxY, nv.y + nv.height);
   368→    }
   369→
   370→    const rect = this.canvasWrap.getBoundingClientRect();
   371→    const pw = rect.width - 40, ph = rect.height - 200;
   372→    const sw = pw / (maxX - minX || 1);
   373→    const sh = ph / (maxY - minY || 1);
   374→    this.viewport.scale = Math.max(0.2, Math.min(1.5, Math.min(sw, sh)));
   375→    this.viewport.x = (rect.width - (maxX - minX) * this.viewport.scale) / 2 - minX * this.viewport.scale;
   376→    this.viewport.y = (ph - (maxY - minY) * this.viewport.scale) / 2 - minY * this.viewport.scale + 20;
   377→    this._applyViewport();
   378→  }
   379→
   380→  // ─── 노드 생성 ────────────────────────────────────────────────
   381→
   382→  _addNode(def, x, y) {
   383→    const id = `node-${this.nodeIdCounter++}`;
   384→    const nv = new NodeView(id, def, x, y, this);
   385→    this.nodes.set(id, nv);
   386→    this.nodesLayer.appendChild(nv.el);
   387→    this._selectNode(id);
   388→    return nv;
   389→  }
   390→
   391→  _removeNode(id) {
   392→    // 연결된 와이어 제거
   393→    for (const [wid, wire] of this.wires) {
   394→      if (wire.fromNode === id || wire.toNode === id) {
   395→        this._removeWire(wid);
   396→      }
   397→    }
   398→    const nv = this.nodes.get(id);
   399→    if (nv) { nv.el.remove(); this.nodes.delete(id); }
   400→    if (this.selectedNode === id) this._selectNode(null);
   401→  }
   402→
   403→  _selectNode(id) {
   404→    this.selectedNode = id;
   405→    for (const [nid, nv] of this.nodes) {
   406→      nv.el.classList.toggle('selected', nid === id);
   407→    }
   408→  }
   409→
   410→  // ─── 드래그 ───────────────────────────────────────────────────
   411→
   412→  startNodeDrag(nodeId, e) {
   413→    const nv = this.nodes.get(nodeId);
   414→    this.dragState = {
   415→      nodeId,
   416→      startMouseX: e.clientX,
   417→      startMouseY: e.clientY,
   418→      startNodeX: nv.x,
   419→      startNodeY: nv.y,
   420→    };
   421→    this._selectNode(nodeId);
   422→    e.preventDefault();
   423→  }
   424→
   425→  _onNodeDrag(e) {
   426→    if (!this.dragState) return;
   427→    const { nodeId, startMouseX, startMouseY, startNodeX, startNodeY } = this.dragState;
   428→    const nv = this.nodes.get(nodeId);
   429→    if (!nv) return;
   430→    const dx = (e.clientX - startMouseX) / this.viewport.scale;
   431→    const dy = (e.clientY - startMouseY) / this.viewport.scale;
   432→    nv.x = startNodeX + dx;
   433→    nv.y = startNodeY + dy;
   434→    nv.el.style.left = `${nv.x}px`;
   435→    nv.el.style.top = `${nv.y}px`;
   436→    this._redrawWiresForNode(nodeId);
   437→  }
   438→
   439→  // ─── 와이어 ───────────────────────────────────────────────────
   440→
   441→  startWireDrag(nodeId, portIdx, isOutput, portEl) {
   442→    const pos = this._getPortPos(nodeId, portIdx, isOutput);
   443→    this.wireState = { fromNode: nodeId, fromPort: portIdx, fromOutput: isOutput, startPos: pos };
   444→  }
   445→
   446→  _onWireDrag(e) {
   447→    if (!this.wireState) return;
   448→    const { startPos } = this.wireState;
   449→    const rect = this.canvasWrap.getBoundingClientRect();
   450→    const mx = (e.clientX - rect.left - this.viewport.x) / this.viewport.scale;
   451→    const my = (e.clientY - rect.top - this.viewport.y) / this.viewport.scale;
   452→    this.wirePreview.setAttribute('d', this._bezier(startPos.x, startPos.y, mx, my));
   453→  }
   454→
   455→  _onWireDrop(e) {
   456→    this.wirePreview.setAttribute('d', '');
   457→    if (!this.wireState) return;
   458→    const ws = this.wireState;
   459→    this.wireState = null;
   460→
   461→    // 포트 히트 테스트
   462→    const rect = this.canvasWrap.getBoundingClientRect();
   463→    const mx = e.clientX - rect.left;
   464→    const my = e.clientY - rect.top;
   465→
   466→    for (const [nid, nv] of this.nodes) {
   467→      if (nid === ws.fromNode) continue;
   468→      const portEls = nv.el.querySelectorAll('.fw-port');
   469→      for (const portEl of portEls) {
   470→        const pr = portEl.getBoundingClientRect();
   471→        if (mx >= pr.left - 8 && mx <= pr.right + 8 && my >= pr.top - 8 && my <= pr.bottom + 8) {
   472→          const portIdx = parseInt(portEl.dataset.portIdx);
   473→          const isOutput = portEl.dataset.isOutput === '1';
   474→
   475→          // 방향: 출력→입력 연결만 허용
   476→          let fromNode, fromPort, toNode, toPort;
   477→          if (ws.fromOutput && !isOutput) {
   478→            fromNode = ws.fromNode; fromPort = ws.fromPort;
   479→            toNode = nid; toPort = portIdx;
   480→          } else if (!ws.fromOutput && isOutput) {
   481→            fromNode = nid; fromPort = portIdx;
   482→            toNode = ws.fromNode; toPort = ws.fromPort;
   483→          } else {
   484→            this._showMsg('같은 방향의 포트끼리는 연결할 수 없습니다', 'warn');
   485→            return;
   486→          }
   487→
   488→          // 타입 호환성 체크
   489→          const fromNv = this.nodes.get(fromNode);
   490→          const toNv = this.nodes.get(toNode);
   491→          const outType = fromNv.def.outputs[fromPort]?.portType ?? 'any';
   492→          const inType = toNv.def.inputs[toPort]?.portType ?? 'any';
   493→
   494→          if (!(PORT_COMPAT[outType] ?? []).includes(inType)) {
   495→            this._showMsg(`타입 불일치: ${outType} → ${inType}`, 'error');
   496→            return;
   497→          }
   498→
   499→          this._addWire(fromNode, fromPort, toNode, toPort, outType);
   500→          return;
   501→        }
   502→      }
   503→    }
   504→  }
   505→
   506→  _addWire(fromNode, fromPort, toNode, toPort, portType) {
   507→    // 중복 체크
   508→    for (const w of this.wires.values()) {
   509→      if (w.fromNode === fromNode && w.fromPort === fromPort && w.toNode === toNode && w.toPort === toPort) return;
   510→    }
   511→
   512→    const id = `wire-${this.wireIdCounter++}`;
   513→    const wire = { id, fromNode, fromPort, toNode, toPort, portType };
   514→    this.wires.set(id, wire);
   515→    this._drawWire(wire);
   516→  }
   517→
   518→  _removeWire(id) {
   519→    const el = this.wiresLayer.querySelector(`[data-wire="${id}"]`);
   520→    if (el) el.remove();
   521→    this.wires.delete(id);
   522→  }
   523→
   524→  _drawWire(wire) {
   525→    const from = this._getPortPos(wire.fromNode, wire.fromPort, true);
   526→    const to = this._getPortPos(wire.toNode, wire.toPort, false);
   527→    const color = PORT_COLORS[wire.portType] ?? PORT_COLORS.any;
   528→
   529→    // 기존 제거
   530→    this.wiresLayer.querySelector(`[data-wire="${wire.id}"]`)?.remove();
   531→
   532→    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
   533→    path.setAttribute('data-wire', wire.id);
   534→    path.setAttribute('d', this._bezier(from.x, from.y, to.x, to.y));
   535→    path.setAttribute('fill', 'none');
   536→    path.setAttribute('stroke', color);
   537→    path.setAttribute('stroke-width', '2.5');
   538→    path.setAttribute('opacity', '0.85');
   539→    path.style.cssText = 'cursor:pointer;';
   540→
   541→    path.addEventListener('click', () => {
   542→      if (confirm('이 연결을 삭제하시겠습니까?')) this._removeWire(wire.id);
   543→    });
   544→
   545→    this.wiresLayer.appendChild(path);
   546→  }
   547→
   548→  _redrawWiresForNode(nodeId) {
   549→    for (const wire of this.wires.values()) {
   550→      if (wire.fromNode === nodeId || wire.toNode === nodeId) {
   551→        this._drawWire(wire);
   552→      }
   553→    }
   554→  }
   555→
   556→  _redrawAllWires() {
   557→    for (const wire of this.wires.values()) this._drawWire(wire);
   558→  }
   559→
   560→  _getPortPos(nodeId, portIdx, isOutput) {
   561→    const nv = this.nodes.get(nodeId);
   562→    if (!nv) return { x: 0, y: 0 };
   563→
   564→    const portEls = [...nv.el.querySelectorAll('.fw-port')];
   565→    const target = portEls.find(p => parseInt(p.dataset.portIdx) === portIdx && p.dataset.isOutput === (isOutput ? '1' : '0'));
   566→
   567→    if (!target) {
   568→      return { x: nv.x + (isOutput ? nv.width : 0), y: nv.y + 40 };
   569→    }
   570→
   571→    const canvasRect = this.canvasWrap.getBoundingClientRect();
   572→    const pr = target.getBoundingClientRect();
   573→    return {
   574→      x: (pr.left + pr.width / 2 - canvasRect.left - this.viewport.x) / this.viewport.scale,
   575→      y: (pr.top + pr.height / 2 - canvasRect.top - this.viewport.y) / this.viewport.scale,
   576→    };
   577→  }
   578→
   579→  _bezier(x1, y1, x2, y2) {
   580→    const dx = Math.abs(x2 - x1) * 0.6 + 40;
   581→    return `M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`;
   582→  }
   583→
   584→  // ─── 툴바 액션 ────────────────────────────────────────────────
   585→
   586→  _handleToolbar(action) {
   587→    switch (action) {
   588→      case 'compile': return this._compile();
   589→      case 'run':     return this._run();
   590→      case 'clear':   return this._clearAll();
   591→      case 'export':  return this._exportJSON();
   592→      case 'import':  return this._importJSON();
   593→      case 'fit':     return this._fitView();
   594→    }
   595→  }
   596→
   597→  async _compile() {
   598→    const graph = this._toGraphJSON();
   599→    this._showOutput('컴파일 중...', 'FreeLang');
   600→
   601→    try {
   602→      const res = await fetch('http://localhost:4000/api/compile', {
   603→        method: 'POST',
   604→        headers: { 'Content-Type': 'application/json' },
   605→        body: JSON.stringify({ graph }),
   606→      });
   607→      const data = await res.json();
   608→
   609→      if (data.errors?.length > 0) {
   610→        this._showOutput(`❌ 컴파일 오류:\n${data.errors.join('\n')}`, 'Error');
   611→      } else {
   612→        this._lastCompiledCode = data.code;
   613→        this._showOutput(data.code, 'FreeLang');
   614→        if (data.warnings?.length > 0) {
   615→          this._showOutput(`⚠️ 경고:\n${data.warnings.join('\n')}\n\n` + data.code, 'FreeLang');
   616→        }
   617→      }
   618→    } catch (e) {
   619→      // API 서버 없으면 로컬 컴파일러 사용
   620→      this._showOutput(`API 서버 연결 실패 (localhost:4000)\n로컬 컴파일 실행...\n\n${this._localCompile(graph)}`, 'FreeLang (로컬)');
   621→    }
   622→  }
   623→
   624→  async _run() {
   625→    if (!this._lastCompiledCode) {
   626→      await this._compile();
   627→    }
   628→    if (!this._lastCompiledCode) return;
   629→
   630→    try {
   631→      const res = await fetch('http://localhost:4000/api/execute', {
   632→        method: 'POST',
   633→        headers: { 'Content-Type': 'application/json' },
   634→        body: JSON.stringify({ graph: this._toGraphJSON() }),
   635→      });
   636→      const data = await res.json();
   637→      const out = [
   638→        data.output ? `출력:\n${data.output}` : '',
   639→        data.html ? `HTML:\n${data.html.slice(0, 500)}...` : '',
   640→        data.errors?.length ? `오류:\n${data.errors.join('\n')}` : '',
   641→      ].filter(Boolean).join('\n\n');
   642→      this._showOutput(out || '(출력 없음)', '실행 결과');
   643→    } catch {
   644→      this._showOutput('API 서버 없음. FreeWire 서버를 시작하세요:\nnode src/api/server.js', 'Error');
   645→    }
   646→  }
   647→
   648→  _localCompile(graph) {
   649→    // 간단한 로컬 컴파일 (노드 목록만)
   650→    const lines = [];
   651→    lines.push(`component MyApp {`);
   652→
   653→    const compNodes = Object.values(graph.nodes ?? {}).filter(n => n.type === 'component');
   654→    if (compNodes.length === 0) lines.push('  // 컴포넌트 노드를 추가하세요');
   655→    else {
   656→      lines.push('  markup {');
   657→      for (const n of compNodes) {
   658→        lines.push(`    ${n.subtype} { ${JSON.stringify(n.props ?? {})} }`);
   659→      }
   660→      lines.push('  }');
   661→    }
   662→
   663→    lines.push('}');
   664→    return lines.join('\n');
   665→  }
   666→
   667→  _clearAll() {
   668→    if (this.nodes.size === 0) return;
   669→    if (!confirm('모든 노드와 연결을 삭제하시겠습니까?')) return;
   670→    for (const id of [...this.nodes.keys()]) this._removeNode(id);
   671→    this.wires.clear();
   672→    this.wiresLayer.innerHTML = '';
   673→    this._lastCompiledCode = null;
   674→  }
   675→
   676→  _exportJSON() {
   677→    const json = JSON.stringify(this._toGraphJSON(), null, 2);
   678→    const blob = new Blob([json], { type: 'application/json' });
   679→    const url = URL.createObjectURL(blob);
   680→    const a = document.createElement('a');
   681→    a.href = url; a.download = 'freewire-graph.json'; a.click();
   682→    URL.revokeObjectURL(url);
   683→  }
   684→
   685→  _importJSON() {
   686→    const input = document.createElement('input');
   687→    input.type = 'file'; input.accept = '.json';
   688→    input.onchange = async () => {
   689→      const text = await input.files[0].text();
   690→      try {
   691→        this._fromGraphJSON(JSON.parse(text));
   692→      } catch (e) {
   693→        alert('JSON 파싱 오류: ' + e.message);
   694→      }
   695→    };
   696→    input.click();
   697→  }
   698→
   699→  // ─── 그래프 직렬화 ────────────────────────────────────────────
   700→
   701→  _toGraphJSON() {
   702→    const nodes = {};
   703→    for (const [id, nv] of this.nodes) {
   704→      nodes[id] = {
   705→        id,
   706→        type: nv.def.type,
   707→        subtype: nv.def.subtype,
   708→        label: nv.def.label,
   709→        inputs: nv.def.inputs,
   710→        outputs: nv.def.outputs,
   711→        props: { ...nv.def.props },
   712→        position: { x: nv.x, y: nv.y },
   713→      };
   714→    }
   715→
   716→    const edges = [];
   717→    for (const w of this.wires.values()) {
   718→      edges.push({
   719→        id: w.id,
   720→        from: w.fromNode,
   721→        fromPort: w.fromPort,
   722→        to: w.toNode,
   723→        toPort: w.toPort,
   724→      });
   725→    }
   726→
   727→    return { id: 'freewire-graph', nodes, edges };
   728→  }
   729→
   730→  _fromGraphJSON(json) {
   731→    this._clearAll();
   732→
   733→    for (const [id, nodeData] of Object.entries(json.nodes ?? {})) {
   734→      const def = {
   735→        label: nodeData.label ?? nodeData.subtype,
   736→        type: nodeData.type,
   737→        subtype: nodeData.subtype,
   738→        inputs: nodeData.inputs ?? [],
   739→        outputs: nodeData.outputs ?? [],
   740→        props: nodeData.props ?? {},
   741→      };
   742→      const nv = new NodeView(id, def, nodeData.position?.x ?? 100, nodeData.position?.y ?? 100, this);
   743→      this.nodes.set(id, nv);
   744→      this.nodesLayer.appendChild(nv.el);
   745→    }
   746→
   747→    for (const edge of json.edges ?? []) {
   748→      const fromNv = this.nodes.get(edge.from);
   749→      const outType = fromNv?.def.outputs[edge.fromPort]?.portType ?? 'any';
   750→      this._addWire(edge.from, edge.fromPort, edge.to, edge.toPort, outType);
   751→    }
   752→  }
   753→
   754→  // ─── 출력 ────────────────────────────────────────────────────
   755→
   756→  _showOutput(text, lang = '') {
   757→    this.outputPanel.querySelector('.fw-output-content').textContent = text;
   758→    this.outputPanel.querySelector('.fw-output-lang').textContent = lang ? `[${lang}]` : '';
   759→  }
   760→
   761→  _showMsg(msg, type = 'info') {
   762→    const colors = { info: '#58a6ff', warn: '#d29922', error: '#f85149' };
   763→    const div = document.createElement('div');
   764→    div.style.cssText = `position:fixed;bottom:180px;right:20px;padding:8px 14px;border-radius:6px;background:#21262d;border:1px solid ${colors[type]};color:${colors[type]};font-size:12px;z-index:9999;`;
   765→    div.textContent = msg;
   766→    document.body.appendChild(div);
   767→    setTimeout(() => div.remove(), 3000);
   768→  }
   769→
   770→  destroy() {
   771→    this.nodes.clear();
   772→    this.wires.clear();
   773→  }
   774→}
