   776→// ─── NodeView 클래스 ─────────────────────────────────────────────
   777→
   778→class NodeView {
   779→  constructor(id, def, x, y, editor) {
   780→    this.id = id;
   781→    this.def = { ...def, props: { ...(def.props ?? {}) } };
   782→    this.x = x;
   783→    this.y = y;
   784→    this.editor = editor;
   785→    this.width = 180;
   786→    this.height = 0;
   787→
   788→    this.el = document.createElement('div');
   789→    this.el.className = 'fw-node';
   790→    this.el.style.cssText = `
   791→      position:absolute;left:${x}px;top:${y}px;width:${this.width}px;
   792→      background:#161b22;border:1px solid #30363d;border-radius:8px;
   793→      box-shadow:0 4px 16px rgba(0,0,0,.5);user-select:none;
   794→    `;
   795→    this.el.dataset.nodeId = id;
   796→
   797→    this._render();
   798→    requestAnimationFrame(() => {
   799→      this.height = this.el.offsetHeight;
   800→    });
   801→  }
   802→
   803→  _render() {
   804→    const typeColor = PORT_COLORS[this.def.type] ?? '#8b949e';
   805→    const maxPorts = Math.max(this.def.inputs.length, this.def.outputs.length);
   806→
   807→    const inputRows = this.def.inputs.map((p, i) => `
   808→      <div style="display:flex;align-items:center;gap:6px;padding:3px 8px;">
   809→        <div class="fw-port" data-port-idx="${i}" data-is-output="0" data-node="${this.id}"
   810→          style="width:10px;height:10px;border-radius:50%;background:${PORT_COLORS[p.portType]??'#8b949e'};
   811→          border:2px solid #0d1117;cursor:crosshair;flex-shrink:0;">
   812→        </div>
   813→        <span style="font-size:11px;color:#8b949e;">${p.name}</span>
   814→      </div>
   815→    `).join('');
   816→
   817→    const outputRows = this.def.outputs.map((p, i) => `
   818→      <div style="display:flex;align-items:center;justify-content:flex-end;gap:6px;padding:3px 8px;">
   819→        <span style="font-size:11px;color:#8b949e;">${p.name}</span>
   820→        <div class="fw-port" data-port-idx="${i}" data-is-output="1" data-node="${this.id}"
   821→          style="width:10px;height:10px;border-radius:50%;background:${PORT_COLORS[p.portType]??'#8b949e'};
   822→          border:2px solid #0d1117;cursor:crosshair;flex-shrink:0;">
   823→        </div>
   824→      </div>
   825→    `).join('');
   826→
   827→    // Props 편집 필드
   828→    const propsRows = Object.entries(this.def.props).map(([k, v]) => `
   829→      <div style="display:flex;align-items:center;gap:4px;padding:2px 8px;">
   830→        <span style="font-size:10px;color:#8b949e;min-width:50px;">${k}</span>
   831→        <input class="fw-prop-input" data-key="${k}" value="${v ?? ''}"
   832→          style="flex:1;background:#0d1117;border:1px solid #30363d;color:#e6edf3;padding:2px 6px;border-radius:3px;font-size:11px;min-width:0;">
   833→      </div>
   834→    `).join('');
   835→
   836→    this.el.innerHTML = `
   837→      <div class="fw-node-titlebar"
   838→        style="padding:8px 10px;border-bottom:1px solid #30363d;background:${typeColor}18;
   839→        border-radius:8px 8px 0 0;cursor:move;display:flex;align-items:center;justify-content:space-between;">
   840→        <span style="font-size:12px;font-weight:700;color:${typeColor};">${this.def.label}</span>
   841→        <div style="display:flex;gap:4px;">
   842→          <span style="font-size:9px;color:#8b949e;padding:1px 5px;background:#21262d;border-radius:3px;">${this.def.type}</span>
   843→          <button class="fw-node-del" style="background:none;border:none;color:#8b949e;cursor:pointer;padding:0 2px;font-size:13px;line-height:1;">✕</button>
   844→        </div>
   845→      </div>
   846→      <div style="display:grid;grid-template-columns:1fr 1fr;gap:2px;padding:4px 0;">
   847→        <div class="fw-inputs">${inputRows}</div>
   848→        <div class="fw-outputs">${outputRows}</div>
   849→      </div>
   850→      ${propsRows ? `<div style="border-top:1px solid #30363d;padding:4px 0;">${propsRows}</div>` : ''}
   851→    `;
   852→
   853→    this._bindNodeEvents();
   854→  }
   855→
   856→  _bindNodeEvents() {
   857→    // 드래그
   858→    const titlebar = this.el.querySelector('.fw-node-titlebar');
   859→    titlebar.addEventListener('mousedown', (e) => {
