   691→<script>
   692→// ─── Phase 8-10: 학습 엔진 (인라인) ────────────────────────────
   693→
   694→/**
   695→ * RepairHistory — 수정 이력 축적 + 패턴 인덱스
   696→ */
   697→const HISTORY_STORAGE_KEY = 'freewire:repair-history:v1';
   698→
   699→class RepairHistoryBrowser {
   700→  constructor(maxRecords = 500) {
   701→    this._records      = [];
   702→    this._maxRecords   = maxRecords;
   703→    this._patternIndex = new Map();
   704→    this._efficacyIndex= new Map();
   705→  }
   706→
   707→  record(sessionId, violation, patch, resultScore, previousScore) {
   708→    const improved = resultScore > previousScore;
   709→    const rec = { sessionId, timestamp: Date.now(), violation, patch, resultScore, improved };
   710→    this._records.push(rec);
   711→    if (this._records.length > this._maxRecords) this._records.shift();
   712→
   713→    const pk = `${violation.nodeSubtype ?? '*'}:${violation.fact}`;
   714→    const pp = this._patternIndex.get(pk) ?? { count: 0, improvedCount: 0 };
   715→    this._patternIndex.set(pk, { count: pp.count + 1, improvedCount: pp.improvedCount + (improved ? 1 : 0), lastSeen: rec.timestamp });
   716→
   717→    if (patch) {
   718→      const ek = `${patch.type}:${violation.repairHint}`;
   719→      const ep = this._efficacyIndex.get(ek) ?? { applied: 0, improved: 0 };
   720→      this._efficacyIndex.set(ek, { applied: ep.applied + 1, improved: ep.improved + (improved ? 1 : 0) });
   721→    }
   722→
   723→    this._persist();
   724→    return rec;
   725→  }
   726→
   727→  patternCount(subtype, fact) {
   728→    return this._patternIndex.get(`${subtype ?? '*'}:${fact}`)?.count ?? 0;
   729→  }
   730→
   731→  topViolations(n = 5) {
   732→    return [...this._patternIndex.entries()]
   733→      .map(([key, v]) => ({ pattern: key, ...v }))
   734→      .sort((a, b) => b.count - a.count)
   735→      .slice(0, n);
   736→  }
   737→
   738→  patchEfficacy(patchType, repairHint) {
   739→    const e = this._efficacyIndex.get(`${patchType}:${repairHint}`);
   740→    if (!e || e.applied === 0) return 0.5;
   741→    return e.improved / e.applied;
   742→  }
   743→
   744→  stats() {
   745→    const total = this._records.length;
   746→    const improved = this._records.filter(r => r.improved).length;
   747→    const oldest = this._records[0]?.timestamp ?? null;
   748→    return {
   749→      totalRecords:   total,
   750→      improvedCount:  improved,
   751→      successRate:    total > 0 ? Math.round((improved / total) * 100) : 0,
   752→      uniquePatterns: this._patternIndex.size,
   753→      topViolations:  this.topViolations(3),
   754→      since:          oldest ? new Date(oldest).toLocaleDateString('ko-KR') : null,
   755→    };
   756→  }
   757→
   758→  clear() {
   759→    this._records = [];
   760→    this._patternIndex.clear();
   761→    this._efficacyIndex.clear();
   762→    try { localStorage.removeItem(HISTORY_STORAGE_KEY); } catch (_) {}
   763→  }
   764→
   765→  _persist() {
   766→    try {
   767→      localStorage.setItem(HISTORY_STORAGE_KEY, JSON.stringify({
   768→        records:      this._records,
   769→        patternIndex: [...this._patternIndex.entries()],
   770→        efficacyIndex:[...this._efficacyIndex.entries()],
   771→      }));
   772→    } catch (_) {}
   773→  }
   774→
   775→  _restore() {
   776→    try {
   777→      const raw = localStorage.getItem(HISTORY_STORAGE_KEY);
   778→      if (!raw) return false;
   779→      const data = JSON.parse(raw);
   780→      this._records       = data.records       ?? [];
   781→      this._patternIndex  = new Map(data.patternIndex  ?? []);
   782→      this._efficacyIndex = new Map(data.efficacyIndex ?? []);
   783→      while (this._records.length > this._maxRecords) this._records.shift();
   784→      return true;
   785→    } catch (_) { return false; }
   786→  }
   787→}
   788→
   789→// 전역 이력 — localStorage 복원 포함
   790→const GLOBAL_HISTORY = new RepairHistoryBrowser(1000);
   791→const _historyRestored = GLOBAL_HISTORY._restore();
   792→
   793→/**
   794→ * PatternAdvisor (브라우저 버전)
   795→ */
   796→function getPatternAdvice(nodesArr) {
   797→  const advices = [];
   798→  const subs = nodesArr.map(n => n.subtype);
   799→
   800→  const RISK_PATTERNS = [
   801→    {
   802→      fact: 'ui.button.connected',
   803→      condition: ss => ss.includes('button') && !ss.includes('handler'),
   804→      message: n => `버튼+핸들러 누락이 ${n}번 반복됨 — 주의 필요`,
   805→      severity: n => n >= 5 ? 'high' : n >= 2 ? 'medium' : 'low',
   806→    },
   807→    {
   808→      fact: 'state.bound',
   809→      condition: ss => ss.includes('state') && !ss.includes('text'),
   810→      message: n => `상태-텍스트 바인딩 누락이 ${n}번 반복됨`,
   811→      severity: n => n >= 3 ? 'high' : 'medium',
   812→    },
   813→  ];
   814→
   815→  for (const rp of RISK_PATTERNS) {
   816→    if (!rp.condition(subs)) continue;
   817→    const count = GLOBAL_HISTORY.patternCount('button', rp.fact) +
   818→                  GLOBAL_HISTORY.patternCount('state', rp.fact) +
   819→                  GLOBAL_HISTORY.patternCount('*', rp.fact);
   820→    if (count === 0) continue;
   821→    advices.push({ fact: rp.fact, occurrences: count, severity: rp.severity(count), message: rp.message(count) });
   822→  }
   823→  return advices.sort((a, b) => b.occurrences - a.occurrences);
   824→}
   825→
   826→// ─── Intent 엔진 (인라인 브라우저 번들) ────────────────────────
   827→
   828→const INTENT_DEFAULTS = {
   829→  button:    { produces: ['ui.button.clickable'], ensures: ['action.triggered'], warns: ['ui.button.connected'] },
   830→  input:     { produces: ['data.available'] },
   831→  text:      { produces: ['output.displayed'] },
   832→  card:      { produces: ['ui.rendered'] },
   833→  container: { produces: ['ui.rendered'] },
   834→  state:     { produces: ['state.initialized', 'data.available'] },
   835→  handler:   { produces: ['action.handler.present', 'ui.button.connected'], requires: ['ui.button.clickable'] },
   836→  setState:  { produces: ['state.bound'], requires: ['action.handler.present', 'state.initialized'] },
   837→};
   838→
   839→function intentGetContract(subtype) {
   840→  return INTENT_DEFAULTS[subtype] ?? { produces: [], requires: [], ensures: [], warns: [] };
   841→}
   842→
   843→function intentParseGoal(text) {
   844→  const t = (text || '').toLowerCase();
   845→  const facts = new Set(['ui.rendered']);
   846→  if (/로그인|login/.test(t))    ['auth.initiated','ui.button.connected','form.email.filled','form.password.filled'].forEach(f=>facts.add(f));
   847→  if (/카운터|counter/.test(t))  ['state.bound','ui.button.connected','output.displayed'].forEach(f=>facts.add(f));
   848→  if (/검색|search/.test(t))     ['data.available','ui.button.connected','output.displayed'].forEach(f=>facts.add(f));
   849→  if (/폼|form|회원가입/.test(t)) ['form.submitted','data.available','ui.button.connected'].forEach(f=>facts.add(f));

