   850→  if (/버튼|button/.test(t))     ['ui.button.clickable','action.triggered'].forEach(f=>facts.add(f));
   851→  return [...facts];
   852→}
   853→
   854→function intentEvaluate(nodes, wires, goal) {
   855→  const nodesArr = [...nodes.values()].map(v => v.def ?? v);
   856→  const wiresArr = [...wires.values()];
   857→  const violations = [];
   858→  const satisfied = new Set();
   859→
   860→  if (nodesArr.length === 0) {
   861→    violations.push({ type:'structural', fact:'graph.nonempty', msg:'노드가 없습니다.', severity:'error', nodeLabel:'그래프', repairHint:'add_node' });
   862→    return buildIntentReport(violations, satisfied, goal);
   863→  }
   864→
   865→  // 각 노드 계약 확인
   866→  for (const n of nodesArr) {
   867→    const c = intentGetContract(n.subtype);
   868→    const inputFacts = new Set();
   869→    wiresArr.filter(w=>(w.tn??w.to)===n.id).forEach(w => {
   870→      const src = nodesArr.find(s=>s.id===(w.fn??w.from));
   871→      if (src) intentGetContract(src.subtype).produces?.forEach(f=>inputFacts.add(f));
   872→    });
   873→    (c.requires||[]).forEach(req => {
   874→      if (!inputFacts.has(req) && !satisfied.has(req)) {
   875→        violations.push({ type:'requires', fact:req, msg:`"${req}" 조건 미충족`, severity:'error', nodeLabel:n.label??n.subtype, repairHint:`connect_${req.split('.')[0]}` });
   876→      }
   877→    });
   878→    (c.warns||[]).forEach(w => {
   879→      if (!inputFacts.has(w)) violations.push({ type:'warning', fact:w, msg:`"${w}" 권장`, severity:'warning', nodeLabel:n.label??n.subtype, repairHint:`enhance_${w}` });
   880→    });
   881→    (c.produces||[]).concat(c.ensures||[]).forEach(f=>satisfied.add(f));
   882→  }
   883→
   884→  // 버튼↔핸들러 체크
   885→  const buttons  = nodesArr.filter(n=>n.subtype==='button');
   886→  const handlers = nodesArr.filter(n=>n.subtype==='handler');
   887→  if (buttons.length > 0 && handlers.length === 0) {
   888→    violations.push({ type:'structural', fact:'action.handler.present', msg:`버튼 ${buttons.length}개에 핸들러 없음 — 클릭이 동작하지 않습니다`, severity:'error', nodeLabel:'그래프', repairHint:'add_handler_node' });
   889→  }
   890→  for (const b of buttons) {
   891→    const connected = wiresArr.some(w=>(w.tn??w.to)===b.id&&(w.tp??w.toPort)===1);
   892→    if (!connected && handlers.length > 0) {
   893→      violations.push({ type:'structural', fact:'ui.button.connected', msg:`버튼 "${b.props?.label??b.id}"에 핸들러 미연결`, severity:'error', nodeLabel:b.label??'버튼', repairHint:'wire_handler_to_button', nodeId:b.id });
   894→    }
   895→  }
   896→
   897→  // state↔text 바인딩 체크
   898→  const stateNodes = nodesArr.filter(n=>n.subtype==='state');
   899→  const textNodes  = nodesArr.filter(n=>n.subtype==='text');
   900→  for (const st of stateNodes) {
   901→    const hasOut = wiresArr.some(w=>(w.fn??w.from)===st.id);
   902→    if (!hasOut && textNodes.length > 0) {
   903→      violations.push({ type:'structural', fact:'state.bound', msg:`상태 "${st.props?.name??st.id}"가 UI에 바인딩 안 됨`, severity:'warning', nodeLabel:st.label??'상태', repairHint:'wire_state_to_display', nodeId:st.id });
   904→    } else if (hasOut) satisfied.add('state.bound');
   905→  }
   906→
   907→  return buildIntentReport(violations, satisfied, goal);
   908→}
   909→
   910→function buildIntentReport(violations, satisfied, goal) {
   911→  const errors   = violations.filter(v=>v.severity==='error');
   912→  const warnings = violations.filter(v=>v.severity==='warning');
   913→  const goalFacts = intentParseGoal(goal);
   914→  const satisfiedGoals = goalFacts.filter(f=>satisfied.has(f));
   915→  const score = goalFacts.length > 0
   916→    ? Math.round((satisfiedGoals.length / goalFacts.length) * 100)
   917→    : (errors.length === 0 ? 100 : 20);
   918→  return { score, passed: errors.length===0, errors, warnings, violations, satisfiedFacts:[...satisfied], missingFacts: goalFacts.filter(f=>!satisfied.has(f)) };
   919→}
   920→
   921→function intentAutoRepair(nodes, wires, violations, nextId) {
   922→  const nodesArr = [...nodes.values()].map(v=>v.def??v);
   923→  const applied = [];
   924→
   925→  for (const v of violations) {
   926→    if (v.repairHint === 'add_handler_node') {
   927→      const btn = nodesArr.find(n=>n.subtype==='button');
   928→      if (!btn) continue;
   929→      const handlerName = /로그인|login/i.test(btn.props?.label) ? 'handleLogin' : /\+/.test(btn.props?.label) ? 'handleIncrement' : 'handleClick';
   930→      const nid = nextId();
   931→      const newNode = {
   932→        id:nid, type:'logic', subtype:'handler', label:`핸들러[${handlerName}]`,
   933→        inputs:[{name:'action',portType:'logic'}], outputs:[{name:'handler',portType:'logic'}],
   934→        props:{name:handlerName}, position:{x:(btn.position?.x??300)+230, y:(btn.position?.y??100)},
   935→      };
   936→      nodes.set(nid, newNode);
   937→      const wid = nextId();
   938→      wires.set(wid, {id:wid, fn:nid, fp:0, tn:btn.id, tp:1});
   939→      applied.push(`핸들러 "${handlerName}" 추가 + 버튼 연결`);
   940→    }
   941→
   942→    else if (v.repairHint === 'wire_handler_to_button') {
   943→      const handlerNode = nodesArr.find(n=>n.subtype==='handler');
   944→      if (!handlerNode || !v.nodeId) continue;
   945→      const alreadyWired = [...wires.values()].some(w=>w.fn===handlerNode.id && w.tn===v.nodeId && w.tp===1);
   946→      if (!alreadyWired) {
   947→        const wid = nextId();
   948→        wires.set(wid, {id:wid, fn:handlerNode.id, fp:0, tn:v.nodeId, tp:1});
   949→        applied.push(`핸들러 → 버튼 연결`);
   950→      }
   951→    }
   952→
   953→    else if (v.repairHint === 'wire_state_to_display') {
   954→      const stateNode = nodesArr.find(n=>n.id===v.nodeId || n.subtype==='state');
   955→      const textNode  = nodesArr.find(n=>n.subtype==='text');
   956→      if (!stateNode || !textNode) continue;
   957→      const alreadyWired = [...wires.values()].some(w=>w.fn===stateNode.id && w.tn===textNode.id);
   958→      if (!alreadyWired) {
   959→        const wid = nextId();
   960→        wires.set(wid, {id:wid, fn:stateNode.id, fp:0, tn:textNode.id, tp:0});
   961→        applied.push(`상태 → 텍스트 바인딩`);
   962→      }
   963→    }
   964→  }
   965→
   966→  return applied;
   967→}
