   969→function intentGetNodeViewId(nodes, nodeId) {
   970→  // NodeView Map에서 해당 def.id를 가진 뷰 찾기
   971→  for (const [vid, view] of nodes) {
   972→    if ((view.def?.id ?? view.id) === nodeId) return vid;
   973→  }
   974→  return nodeId;
