   977→// ─── 브라우저 미니 컴파일러 (노드 그래프 → HTML) ───────────────
   978→
   979→/**
   980→ * 노드 그래프 → { html, css, js, freelang } 변환
   981→ * FreeExecutor 브라우저 포트. 서버 불필요.
   982→ */
   983→function browserCompile(nodes, wires) {
   984→  const nodesArr = [...nodes.values()].map(v => v.def ?? v);
   985→  const wiresArr = [...wires.values()];
   986→
   987→  // 노드 타입 분류
   988→  const stateNodes  = nodesArr.filter(n => n.type === 'data' && n.subtype === 'state');
   989→  const constNodes  = nodesArr.filter(n => n.type === 'data' && n.subtype === 'const');
   990→  const compNodes   = nodesArr.filter(n => n.type === 'component');
   991→  const handlerNodes= nodesArr.filter(n => n.type === 'logic' && n.subtype === 'handler');
   992→
   993→  // ── FreeLang 코드 생성 ──────────────────────────
   994→  const freelang = generateFreeLang(nodesArr, wiresArr, stateNodes, constNodes, compNodes, handlerNodes);
   995→
   996→  // ── CSS ─────────────────────────────────────────
   997→  const css = generateCSS(compNodes);
   998→
   999→  // ── JS ──────────────────────────────────────────
  1000→  const js = generateJS(stateNodes, handlerNodes, nodesArr);
  1001→
  1002→  // ── HTML ─────────────────────────────────────────
  1003→  const html = generateHTML(compNodes, stateNodes, nodesArr, wiresArr);
  1004→
  1005→  return { html, css, js, freelang };
  1006→}
  1007→
  1008→function generateFreeLang(nodesArr, wiresArr, stateNodes, constNodes, compNodes, handlerNodes) {
  1009→  const lines = ['component MyApp {'];
  1010→
  1011→  if (stateNodes.length) {
  1012→    lines.push('  state {');
  1013→    stateNodes.forEach(n => lines.push(`    ${n.props?.name ?? 'value'}: ${n.props?.initial ?? '0'}`));
  1014→    lines.push('  }');
  1015→  }
  1016→
  1017→  if (compNodes.length) {
  1018→    lines.push('  markup {');
  1019→    compNodes.forEach(n => {
  1020→      const p = n.props ?? {};
  1021→      if (n.subtype === 'button')    lines.push(`    button(label: "${p.label ?? '버튼'}", variant: "${p.variant ?? 'primary'}")`);
  1022→      else if (n.subtype === 'text') lines.push(`    text(content: "${p.content ?? '텍스트'}", tag: "${p.tag ?? 'p'}")`);
  1023→      else if (n.subtype === 'input') lines.push(`    input(placeholder: "${p.placeholder ?? ''}", type: "${p.type ?? 'text'}")`);
  1024→      else if (n.subtype === 'card') lines.push(`    card(title: "${p.title ?? '카드'}")`);
  1025→      else if (n.subtype === 'container') lines.push(`    container(direction: "${p.direction ?? 'column'}")`);
  1026→    });
  1027→    lines.push('  }');
  1028→  }
  1029→
  1030→  lines.push('}');
  1031→  return lines.join('\n');
  1032→}
