  1060→function generateJS(stateNodes, handlerNodes, nodesArr) {
  1061→  if (stateNodes.length === 0 && handlerNodes.length === 0) return '';
  1062→
  1063→  const lines = ['(function() { "use strict";'];
  1064→
  1065→  // state
  1066→  stateNodes.forEach(n => {
  1067→    const name = n.props?.name ?? 'value';
  1068→    const init = n.props?.initial ?? '0';
  1069→    lines.push(`  var ${name} = ${isNaN(init) ? JSON.stringify(init.replace(/^"|"$/g,'')) : init};`);
  1070→  });
  1071→
  1072→  // _updateDOM
  1073→  lines.push('  function _updateDOM() {');
  1074→  stateNodes.forEach(n => {
  1075→    const name = n.props?.name ?? 'value';
  1076→    lines.push(`    document.querySelectorAll('[data-bind="${name}"]').forEach(function(el){ el.textContent = ${name}; });`);
  1077→  });
  1078→  lines.push('  }');
  1079→
  1080→  // 버튼 이벤트
  1081→  const btnNodes = nodesArr.filter(n => n.subtype === 'button');
  1082→  btnNodes.forEach((n, i) => {
  1083→    const label = n.props?.label ?? '';
  1084→    const btnId = `fw-btn-${n.id ?? i}`;
  1085→    const stateTarget = stateNodes[0];
  1086→    if (stateTarget) {
  1087→      const name = stateTarget.props?.name ?? 'value';
  1088→      if (/\+/.test(label)) lines.push(`  function _click_${i}(){ ${name}++; _updateDOM(); }`);
  1089→      else if (/-/.test(label)) lines.push(`  function _click_${i}(){ ${name}--; _updateDOM(); }`);
  1090→      else if (/초기화|reset/i.test(label)) lines.push(`  function _click_${i}(){ ${name} = 0; _updateDOM(); }`);
  1091→      else lines.push(`  function _click_${i}(){ _updateDOM(); }`);
  1092→    } else {
  1093→      lines.push(`  function _click_${i}(){ _updateDOM(); }`);
  1094→    }
  1095→  });
  1096→
  1097→  lines.push('  document.addEventListener("DOMContentLoaded", function() {');
  1098→  btnNodes.forEach((n, i) => {
  1099→    lines.push(`    var b${i}=document.querySelector('[data-fw-id="${n.id ?? i}"]');`);
  1100→    lines.push(`    if(b${i}) b${i}.addEventListener("click", _click_${i});`);
  1101→  });
  1102→  lines.push('    _updateDOM();');
  1103→  lines.push('  });');
  1104→  lines.push('})();');
  1105→  return lines.join('\n');
  1106→}
