  1108→function generateHTML(compNodes, stateNodes, nodesArr, wiresArr) {
  1109→  // 위상 정렬: 컨테이너/카드가 자식 먼저 삽입되는 순서
  1110→  const parts = [];
  1111→
  1112→  // 카드/컨테이너 감지
  1113→  const containers = compNodes.filter(n => n.subtype === 'card' || n.subtype === 'container');
  1114→  const inContainer = new Set();
  1115→
  1116→  // 컨테이너에 연결된 자식 수집
  1117→  const childrenOf = {};
  1118→  for (const c of containers) {
  1119→    childrenOf[c.id] = [];
  1120→  }
  1121→  for (const w of wiresArr) {
  1122→    const srcDef = nodesArr.find(n => n.id === (w.fn ?? w.from));
  1123→    const dstDef = nodesArr.find(n => n.id === (w.tn ?? w.to));
  1124→    if (srcDef && dstDef && childrenOf[dstDef.id] !== undefined) {
  1125→      childrenOf[dstDef.id].push(srcDef);
  1126→      inContainer.add(srcDef.id);
  1127→    }
  1128→  }
  1129→
  1130→  function nodeToHTML(n) {
  1131→    const p = n.props ?? {};
  1132→    const id = n.id ?? '';
  1133→    if (n.subtype === 'button') {
  1134→      const cls = p.variant ?? 'primary';
  1135→      const stateTarget = stateNodes[0];
  1136→      const bindAttr = stateTarget ? ` data-bind="${stateTarget.props?.name}"` : '';
  1137→      return `<button class="${cls}" data-fw-id="${id}">${p.label ?? '버튼'}</button>`;
  1138→    }
  1139→    if (n.subtype === 'text') {
  1140→      const tag = p.tag ?? 'p';
  1141→      const connState = stateNodes.find(s => wiresArr.some(w => (w.fn ?? w.from) === s.id && (w.tn ?? w.to) === n.id));
  1142→      const content = connState
  1143→        ? `<span data-bind="${connState.props?.name}">${connState.props?.initial ?? '0'}</span>`
  1144→        : (p.content ?? '텍스트');
  1145→      return `<${tag}>${content}</${tag}>`;
  1146→    }
  1147→    if (n.subtype === 'input') {
  1148→      return `<input type="${p.type ?? 'text'}" placeholder="${p.placeholder ?? ''}" />`;
  1149→    }
  1150→    if (n.subtype === 'card') {
  1151→      const children = (childrenOf[id] ?? []).map(nodeToHTML).join('\n      ');
  1152→      return `<div class="card">\n      <div class="card-title">${p.title ?? '카드'}</div>\n      ${children}\n    </div>`;
  1153→    }
  1154→    if (n.subtype === 'container') {
  1155→      const dir = p.direction === 'row' ? 'row' : 'col';
  1156→      const children = (childrenOf[id] ?? []).map(nodeToHTML).join('\n      ');
  1157→      return `<div class="container-${dir}">\n      ${children}\n    </div>`;
  1158→    }
  1159→    return '';
  1160→  }
  1161→
  1162→  // 최상위 노드만 렌더링 (컨테이너에 속하지 않은 것)
  1163→  for (const n of compNodes) {
  1164→    if (!inContainer.has(n.id)) {
  1165→      const html = nodeToHTML(n);
  1166→      if (html) parts.push('    ' + html);
  1167→    }
  1168→  }
  1169→
  1170→  // 노드가 없으면 플레이스홀더
  1171→  if (parts.length === 0) {
  1172→    return '<div class="fw-app"><p style="color:#94a3b8;text-align:center">노드를 추가하고 ▶ 실행을 누르세요</p></div>';
  1173→  }
  1174→
  1175→  return `<div class="fw-app">\n${parts.join('\n')}\n  </div>`;
  1176→}
