  1365→function aiParseIntent(text) {
  1366→  const t = text.toLowerCase().trim();
  1367→  for (const [pat, type] of AI_PATTERNS) {
  1368→    if (pat.test(t)) return type;
  1369→  }
  1370→  return 'generic';
  1371→}
  1372→
  1373→function aiLayout(nodes, offsetX=100, offsetY=80) {
  1374→  const W=200, H=140, GAP_X=60, GAP_Y=30;
  1375→  const layers = { data:[], logic:[], component:[] };
  1376→  for (const n of nodes) { (layers[n.type] || layers.component).push(n); }
  1377→  const pos = {}; let baseX = offsetX;
  1378→  for (const [, layerNodes] of Object.entries(layers)) {
  1379→    if (!layerNodes.length) continue;
  1380→    layerNodes.forEach((n, i) => { pos[n.id] = { x:baseX, y:offsetY + i*(H+GAP_Y) }; });
  1381→    baseX += W + GAP_X;
  1382→  }
  1383→  return pos;
  1384→}
