  1386→// API 키 — localStorage에서 복원
  1387→let _claudeApiKey = localStorage.getItem('freewire:claude-api-key') || '';
  1388→
  1389→function saveApiKey(key) {
  1390→  _claudeApiKey = key.trim();
  1391→  if (_claudeApiKey) localStorage.setItem('freewire:claude-api-key', _claudeApiKey);
  1392→  else localStorage.removeItem('freewire:claude-api-key');
  1393→}
  1394→
  1395→async function aiGenerate(text) {
  1396→  // Claude API 시도 (서버 경유)
  1397→  if (_claudeApiKey || true) {  // 서버가 env key도 사용
  1398→    try {
  1399→      const resp = await fetch('http://localhost:4010/api/ai-generate', {
  1400→        method: 'POST',
  1401→        headers: { 'Content-Type': 'application/json' },
  1402→        body: JSON.stringify({ prompt: text, apiKey: _claudeApiKey }),
  1403→        signal: AbortSignal.timeout(20000),
  1404→      });
  1405→      if (resp.ok) {
  1406→        const data = await resp.json();
  1407→        const graph = data.graph;
  1408→        // nodes 배열 → 객체 맵
  1409→        const nodesMap = {};
  1410→        for (const n of graph.nodes) {
  1411→          nodesMap[n.id] = n;
  1412→        }
  1413→        return {
  1414→          nodes: nodesMap,
  1415→          edges: graph.edges,
  1416→          label: graph.label,
  1417→          nodeCount: graph.nodes.length,
  1418→          source: 'claude',
  1419→          model: data.model,
  1420→        };
  1421→      }
  1422→      // 서버 오류면 fallback
  1423→      const err = await resp.json().catch(() => ({}));
  1424→      console.warn('[AI] 서버 오류, 템플릿 폴백:', err.error);
  1425→    } catch (e) {
  1426→      console.warn('[AI] 서버 연결 실패, 템플릿 폴백:', e.message);
  1427→    }
  1428→  }
  1429→
  1430→  // 템플릿 폴백
  1431→  const type = aiParseIntent(text);
  1432→  const tmpl = AI_TEMPLATES[type];
  1433→  const raw = tmpl ? tmpl(text) : AI_TEMPLATES['input-form']();
  1434→  const positions = aiLayout(raw.nodes);
  1435→  const nodes = {};
  1436→  for (const n of raw.nodes) {
  1437→    nodes[n.id] = { ...n, position: positions[n.id] ?? { x:100, y:80 } };
  1438→  }
  1439→  const edges = raw.edges.map((e, i) => ({ id:`ae-${i}`, ...e }));
  1440→  return { nodes, edges, label:raw.label, intent:type, nodeCount:raw.nodes.length, source:'template' };
  1441→}
