  2486→      const fromId = idMap[e.from], toId = idMap[e.to];
  2487→      if (fromId && toId && editor.nodes.has(fromId) && editor.nodes.has(toId)) {
  2488→        const wireId = `n${editor.nodeIdCtr++}`;
  2489→        editor.wires.set(wireId, { id:wireId, fn:fromId, fp:e.fromPort??0, tn:toId, tp:e.toPort??0 });
  2490→      }
  2491→    }
  2492→
  2493→    editor._redrawAll();
