  2495→
  2496→    const srcBadge = result.source === 'claude'
  2497→      ? `<span style="color:var(--accent);font-size:10px"> [Claude ${result.model?.includes('haiku') ? 'Haiku' : 'AI'}]</span>`
  2498→      : `<span style="color:var(--dim);font-size:10px"> [템플릿]</span>`;
