  2504→    setTimeout(() => { aiStatus.textContent = ''; }, 3000);
  2505→  } catch (err) {
  2506→    aiStatus.textContent = `❌ 오류: ${err.message}`;
  2507→    aiStatus.style.color = 'var(--red)';
  2508→  }
  2509→}
